// QA joint for device-pairing (box 4.1): the WHOLE pairing contract walked
// over the REAL composed graph — a temp sqlite store, the real pairing
// Service, the real api.New router (both auth postures live: the bare pair
// group and the browse/admin groups behind the real authMiddleware), and the
// composed web.Handler whose /openapi.json serves the committed internal/web/
// api/openapi.json bytes (go:embed). No mocks on any joint: the only mirrored
// shell is the Playback closure cmd/mellifera owns (package main —
// unimportable), mirrored in miniature per the harness contract (the
// main.go:298 shape over the real stream Service's Describe/Issue; Describe
// on the unpacked fixture is pure, so no ffmpeg and no subprocesses).
//
// The flow: unauthenticated POST /pair mints {pairing_id, code}; the admin
// list carries the request with that code; approve flips it; the device's
// wait poll picks the raw token up EXACTLY once (the second poll reports
// consumed with no token key on the wire — INV2); the token resolves
// RoleClient through the real middleware (browse 200, admin verb 403);
// revoking the device 401s the same browse call; and the committed SPA
// contract carries all seven pairing paths.
package itest

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"regexp"
	"testing"
	"time"

	"github.com/mellifera/mellifera/internal/api"
	"github.com/mellifera/mellifera/internal/pairing"
	"github.com/mellifera/mellifera/internal/store"
	"github.com/mellifera/mellifera/internal/stream"
	"github.com/mellifera/mellifera/internal/web"
)

// qaPairingIDRe is the 128-bit capability mint: 16 crypto/rand bytes,
// lowercase hex (pairing D5).
var qaPairingIDRe = regexp.MustCompile(`^[0-9a-f]{32}$`)

// qaPairingCodeRe is the TV-readable code mint: 8 glyphs from the
// unambiguous alphabet — no 0/O and no 1/I/L (pairing D6).
var qaPairingCodeRe = regexp.MustCompile(`^[A-HJKMNP-Z2-9]{8}$`)

// TestPairingJointFlow is the Tier-1 joint round trip of device pairing:
// real store → real pairing Service → real api.New router → composed
// web.Handler, driven over real HTTP end to end.
func TestPairingJointFlow(t *testing.T) {
	ctx := context.Background()
	tmp := t.TempDir()
	st, err := store.Open(ctx, filepath.Join(tmp, "qa-pairing.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })

	// The production pairing wiring (cmd/mellifera/main.go): the real
	// Service over the shared store, time.Now spelled out per the
	// constructor's production contract.
	pairingSvc := pairing.NewService(st, time.Now)

	// The Playback closure's real Describe/Issue collaborator, hermetic
	// knobs only — Describe on the unpacked fixture never touches disk.
	media := &stream.Service{
		Root:   filepath.Join(tmp, "streams"),
		Secret: []byte("qa-pairing-media-secret"),
	}

	const adminToken = "qa-pairing-admin-token"
	apiH := api.New(api.Deps{
		AdminToken: adminToken,
		Store:      st,
		Pairing:    pairingSvc,
		// The cmd/mellifera Playback closure mirrored in miniature (package
		// main is unimportable — the established harness contract): GetItem →
		// Describe + a fresh media token for the cookie delivery.
		Playback: func(ctx context.Context, itemID string) (api.Playback, error) {
			row, err := st.GetItem(ctx, itemID)
			if err != nil {
				return api.Playback{}, err
			}
			var doc map[string]any
			if err := json.Unmarshal(row.Document, &doc); err != nil {
				return api.Playback{}, err
			}
			mode, state, playURL, sections, voiceovers, stateReason := media.Describe(itemID, doc)
			tok, _ := media.Issue(itemID, time.Now())
			return api.Playback{Mode: mode, State: state, PlayURL: playURL, StateReason: stateReason, Sections: sections, Voiceovers: voiceovers, Token: tok}, nil
		},
	})
	// The COMPOSED surface (web.Handler over api.New) — the exact surface
	// behind /api/v1 in production, carrying the public /openapi.json mount.
	srv := httptest.NewServer(web.Handler(apiH, web.Options{}))
	t.Cleanup(srv.Close)
	client := srv.Client()

	// Fixture: one real library row + one real item row ({} document — the
	// unpacked direct-floor item the playback leg reads).
	libID, err := st.CreateLibrary(ctx, "tv", filepath.Join(tmp, "lib"), "QA Pairing")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	if err := st.PutItem(ctx, store.Item{
		ID: "qa-pair-item", ModuleID: "tv", LibraryID: libID, FileID: "qa-pair-file",
		RelativePath: "/show/ep1.mkv", MediaType: "video",
		Document: json.RawMessage(`{}`), SchemaVersion: 1,
	}); err != nil {
		t.Fatalf("PutItem: %v", err)
	}

	// --- leg 1: the unauthenticated pair create (NO Authorization header) ---
	var created map[string]any
	if status := doRequest(t, client, http.MethodPost, srv.URL+"/api/v1/pair", "", nil, &created); status != http.StatusOK {
		t.Fatalf("POST /pair: HTTP %d, want 200", status)
	}
	// The wire shape is EXACTLY {pairing_id, code} — snake_case, nothing else.
	if len(created) != 2 || created["pairing_id"] == nil || created["code"] == nil {
		t.Fatalf("POST /pair body = %v, want exactly the key set {pairing_id, code}", created)
	}
	pairingID, _ := created["pairing_id"].(string)
	code, _ := created["code"].(string)
	if !qaPairingIDRe.MatchString(pairingID) {
		t.Fatalf("pairing_id = %q, want 32 lowercase hex (the 128-bit capability)", pairingID)
	}
	if !qaPairingCodeRe.MatchString(code) {
		t.Fatalf("code = %q, want 8 glyphs from the unambiguous TV alphabet", code)
	}

	// --- leg 2: the admin review surface lists the request with that code ---
	var list struct {
		Pairings []struct {
			PairingID string    `json:"pairing_id"`
			Code      string    `json:"code"`
			CreatedAt time.Time `json:"created_at"`
			ExpiresAt time.Time `json:"expires_at"`
		} `json:"pairings"`
	}
	if status := doRequest(t, client, http.MethodGet, srv.URL+"/api/v1/admin/pairings", adminToken, nil, &list); status != http.StatusOK {
		t.Fatalf("GET /admin/pairings: HTTP %d, want 200", status)
	}
	if len(list.Pairings) != 1 || list.Pairings[0].PairingID != pairingID || list.Pairings[0].Code != code {
		t.Fatalf("pending list = %+v, want exactly the minted request (id %s, code %s)", list.Pairings, pairingID, code)
	}

	// --- leg 3: the operator approves ---
	var approved struct {
		PairingID string `json:"pairing_id"`
		Status    string `json:"status"`
	}
	if status := doRequest(t, client, http.MethodPost, srv.URL+"/api/v1/admin/pairings/"+pairingID+"/approve", adminToken, nil, &approved); status != http.StatusOK {
		t.Fatalf("POST approve: HTTP %d, want 200", status)
	}
	if approved.PairingID != pairingID || approved.Status != "approved" {
		t.Fatalf("approve body = %+v, want {pairing_id %s, status approved}", approved, pairingID)
	}

	// --- leg 4: the device picks the token up EXACTLY once ---
	var pickup map[string]any
	if status := doRequest(t, client, http.MethodGet, srv.URL+"/api/v1/pair/"+pairingID+"/wait", "", nil, &pickup); status != http.StatusOK {
		t.Fatalf("GET wait (first poll): HTTP %d, want 200", status)
	}
	if len(pickup) != 2 || pickup["status"] != "approved" {
		t.Fatalf("first poll = %v, want exactly {status: approved, device_token}", pickup)
	}
	deviceToken, _ := pickup["device_token"].(string)
	if deviceToken == "" {
		t.Fatalf("first poll carried no device_token (an approved request must hand the raw token out)")
	}
	// The SECOND poll: consumed, and the wire body carries NO token key —
	// the token's single ride (pairing INV2).
	var consumed map[string]any
	if status := doRequest(t, client, http.MethodGet, srv.URL+"/api/v1/pair/"+pairingID+"/wait", "", nil, &consumed); status != http.StatusOK {
		t.Fatalf("GET wait (second poll): HTTP %d, want 200", status)
	}
	if len(consumed) != 1 || consumed["status"] != "consumed" {
		t.Fatalf("second poll = %v, want exactly {status: consumed} with no device_token key (INV2 single ride)", consumed)
	}

	// --- leg 5: the device token is RoleClient through the REAL middleware ---
	var pb struct {
		Mode    string `json:"mode"`
		State   string `json:"state"`
		PlayURL string `json:"play_url"`
	}
	if status := doRequest(t, client, http.MethodGet, srv.URL+"/api/v1/items/qa-pair-item/playback", deviceToken, nil, &pb); status != http.StatusOK {
		t.Fatalf("device GET /items/qa-pair-item/playback: HTTP %d, want 200 (RoleClient through the browse group)", status)
	}
	if pb.Mode != "direct" || pb.State != "unsupported" || pb.PlayURL == "" {
		t.Fatalf("descriptor = %+v, want the direct floor over the unpacked fixture (mode direct, a play_url; the empty document carries no ffprobe facts, so the honesty projection fails safe to unsupported)", pb)
	}
	var forbidden struct {
		Error struct {
			Code string `json:"code"`
		} `json:"error"`
	}
	if status := doRequest(t, client, http.MethodPost, srv.URL+"/api/v1/libraries", deviceToken,
		map[string]string{"module_id": "tv", "root_path": "/qa/pairing-forbidden", "display_name": "Nope"}, &forbidden); status != http.StatusForbidden {
		t.Fatalf("device POST /libraries: HTTP %d, want 403 (an admin verb)", status)
	}
	if forbidden.Error.Code != "forbidden" {
		t.Fatalf("device POST /libraries error code = %q, want forbidden (canonical body)", forbidden.Error.Code)
	}

	// --- leg 6: revoking the device kills the credential ---
	var devices struct {
		Devices []map[string]any `json:"devices"`
	}
	if status := doRequest(t, client, http.MethodGet, srv.URL+"/api/v1/admin/devices", adminToken, nil, &devices); status != http.StatusOK {
		t.Fatalf("GET /admin/devices: HTTP %d, want 200", status)
	}
	if len(devices.Devices) != 1 {
		t.Fatalf("devices = %+v, want exactly the one approved device", devices.Devices)
	}
	dev := devices.Devices[0]
	// The registry renders id + code + created_at and NEVER a token (INV3:
	// the raw credential crossed the wire once, at pickup — never from an
	// admin surface).
	if len(dev) != 3 || dev["device_id"] == nil || dev["code"] != code {
		t.Fatalf("device row = %v, want exactly {device_id, code, created_at} with the pairing code %s", dev, code)
	}
	deviceID, _ := dev["device_id"].(string)
	if status := doRequest(t, client, http.MethodDelete, srv.URL+"/api/v1/admin/devices/"+deviceID, adminToken, nil, nil); status != http.StatusNoContent {
		t.Fatalf("DELETE /admin/devices/%s: HTTP %d, want 204", deviceID, status)
	}
	// The SAME browse call now 401s — the deleted token row misses LookupToken.
	if status := doRequest(t, client, http.MethodGet, srv.URL+"/api/v1/items/qa-pair-item/playback", deviceToken, nil, nil); status != http.StatusUnauthorized {
		t.Fatalf("revoked-device playback: HTTP %d, want 401", status)
	}

	// --- leg 7: the committed SPA contract carries all seven pairing paths ---
	// /openapi.json serves the committed internal/web/api/openapi.json bytes
	// (go:embed, swagger.go) — this is the api<->web contract on paper.
	var spec struct {
		Paths map[string]any `json:"paths"`
	}
	if status := doRequest(t, client, http.MethodGet, srv.URL+"/openapi.json", "", nil, &spec); status != http.StatusOK {
		t.Fatalf("GET /openapi.json: HTTP %d, want 200 (public contract)", status)
	}
	for _, path := range []string{
		"/pair", "/pair/{id}/wait",
		"/admin/pairings", "/admin/pairings/{id}/approve", "/admin/pairings/{id}/deny",
		"/admin/devices", "/admin/devices/{id}",
	} {
		if _, ok := spec.Paths[path]; !ok {
			t.Errorf("committed openapi.json missing pairing path %q", path)
		}
	}
}
